from collections import defaultdict

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s) + 1
        mem = defaultdict(int)

        def dfs(i, val):
            if i == len(s):
                return 1
            if (i, val) in mem:
                return mem[(i, val)]
            total = 0
            if s[i] == "D":
                for nxt in range(0, val + 1):
                    total = (total + dfs(i + 1, nxt)) % MOD
            else:
                for nxt in range(val + 1, i + 2):
                    total = (total + dfs(i + 1, nxt)) % MOD
            mem[(i, val)] = total
            return total

        ans = 0
        for start in range(n):
            ans = (ans + dfs(0, start)) % MOD
        return ans

