from typing import List

class Solution:
    def nextGreaterElement(self, nums1: List[int], nums2: List[int]) -> List[int]:
        # Compute next greater for each element in nums2 using a monotonic decreasing stack
        nxt = {}
        stack = []
        for num in nums2:
            while stack and num > stack[-1]:
                nxt[stack.pop()] = num
            stack.append(num)
        # Elements left in stack have no greater element to the right
        for val in stack:
            nxt[val] = -1

        # Map each element in nums1 to its next greater element, default -1
        return [nxt.get(x, -1) for x in nums1]

